// OJO: el nodo Modbus entrega el array en msg.payload.data, no en msg.payload.
const data = msg.payload.data;
if (!Array.isArray(data)) return null;

// Registro 20 = estado del proceso: 1 automático · 2 pausa · 0 parado.
const estado = data[20];
const previo = context.get('estado');
context.set('estado', estado);

// El disparador es el FIN del ciclo (automático → parado), no el paso del tiempo:
// se guarda una fila por carga, no una lectura cada 2 segundos.
if (previo !== 1 || estado !== 0) return null;

// Modbus son enteros de 16 bits: los decimales vienen multiplicados por 100.
const m3 = data[1] / 100;
const duracionSeg = 5 * 60;
const fin = new Date();
const inicio = new Date(fin.getTime() - duracionSeg * 1000);

const nro = (context.get('nro') || 9000) + 1;
context.set('nro', nro);

msg.payload = {
    batch_nro: nro,
    receta: 'H' + data[0],
    m3: m3,
    fecha_hora_inicio: inicio.toISOString(),
    fecha_hora_fin: fin.toISOString(),
    cemento_objetivo: data[9],
    cemento_real: data[10],
    agua_objetivo: data[11],
    agua_real: data[12],
    aridos_objetivo: data[13],
    aridos_real: data[14],
    aditivos_objetivo: data[15] / 100,
    aditivos_real: data[16] / 100,
    operador: 'Ramón'
};

node.status({ fill: 'green', shape: 'dot', text: 'carga ' + nro + ' guardada' });
return msg;
